const int CLK = {{clk_pin}};
const int DT = {{dt_pin}};
volatile long pos = 0;
int lastClk = HIGH;

void isr() {
  int c = digitalRead(CLK);
  if (c != lastClk && c == LOW) {
    if (digitalRead(DT) != c) pos++; else pos--;
  }
  lastClk = c;
}

void setup() {
  pinMode(CLK, INPUT_PULLUP);
  pinMode(DT, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(CLK), isr, CHANGE);
  Serial.begin(115200);
}

void loop() {
  Serial.println(pos);
  delay(200);
}
